executed_malloy:
import "base.malloy"

run: sales_order -> {
  group_by: category is lines.sold_product.CategoryName
  aggregate: margin
  nest: top_5_products is {
    group_by: product is lines.sold_product.ProductName
    aggregate: margin
    order_by: margin desc
    limit: 5
  }
  order_by: category
}
